(()=>{'use strict';const $=id=>document.getElementById(id),p=new URLSearchParams(location.hash.slice(1)),room=p.get('room'),slot=Number(p.get('slot')),token=p.get('token');let peer=null,stream=null,cursor=0,polling=false,timer=null,waiting=[],stopped=true,generation=0;const say=t=>$('phone-status').textContent=t;async function api(method,event){const r=await fetch('/api/studio/rooms/'+room+'/signals?slot='+slot+'&after='+cursor,{method,headers:{'content-type':'application/json','x-studio-token':token},...(event?{body:JSON.stringify({event})}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}async function poll(){if(stopped||polling)return;const attempt=generation,target=peer;polling=true;try{const d=await api('GET');if(attempt!==generation)return;for(const e of d.events){if(e.payload.type==='answer'){await target.setRemoteDescription({type:'answer',sdp:e.payload.sdp});if(attempt!==generation)return;for(const c of waiting)await target.addIceCandidate(c);waiting=[];}else if(e.payload.type==='candidate'){if(target.remoteDescription)await target.addIceCandidate(e.payload.candidate);else waiting.push(e.payload.candidate);}else if(e.payload.type==='stop'){await stop();say('Studio stopped this camera. Press Reconnect camera to pair again while the invitation is valid.');}cursor=e.id;if(attempt!==generation)return;}}catch(e){if(attempt!==generation)return;say(e.message);if(/ended|invalid/i.test(e.message))await stop();}finally{if(attempt===generation){polling=false;if(!stopped)timer=setTimeout(poll,1000);}}}
async function stop(){generation++;stopped=true;polling=false;clearTimeout(timer);waiting=[];const previous=peer;peer=null;previous?.close();stream?.getTracks().forEach(t=>t.stop());stream=null;$('phone-preview').srcObject=null;$('phone-start').disabled=false;$('phone-start').textContent='Reconnect camera';$('phone-stop').disabled=true;$('phone-facing').disabled=false;$('phone-audio').disabled=false;}
async function discardOldSignals(attempt){for(let page=0;page<80;page++){const d=await api('GET');if(attempt!==generation)return false;for(const e of d.events)cursor=e.id;if(d.events.length<100)return true;}throw Error('This invitation has too much connection history. Ask the Studio owner to start a new session.');}
$('phone-start').onclick=async()=>{if(!room||!token||!Number.isInteger(slot)||slot<1||slot>5){say('Open the camera link provided by your studio.');return;}if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection){say('This browser does not support camera pairing. Try an up-to-date Chrome or Safari browser.');return;}$('phone-start').disabled=true;let attempt;try{await stop();attempt=generation;$('phone-start').disabled=true;$('phone-stop').disabled=false;$('phone-facing').disabled=true;$('phone-audio').disabled=true;if(!await discardOldSignals(attempt))return;const acquired=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:$('phone-facing').value},width:{ideal:1280},height:{ideal:720},frameRate:{ideal:24,max:30}},audio:$('phone-audio').checked?{echoCancellation:true}:false});if(attempt!==generation){acquired.getTracks().forEach(t=>t.stop());return;}stream=acquired;$('phone-preview').srcObject=stream;peer=new RTCPeerConnection({iceServers:[]});stream.getTracks().forEach(t=>peer.addTrack(t,stream));const target=peer;let offerSent=false;const outbound=[];peer.onicecandidate=e=>{if(attempt!==generation||peer!==target)return;if(e.candidate){if(offerSent)api('POST',{type:'candidate',candidate:e.candidate.toJSON()}).catch(e=>say(e.message));else outbound.push(e.candidate.toJSON());}};peer.onconnectionstatechange=()=>{if(attempt!==generation||peer!==target)return;const state=target.connectionState;if(state==='failed'){stop();say('Connection failed. Check shared Wi-Fi, then press Reconnect camera.');}else say(state==='connected'?'Connected — your studio is receiving this camera.':state==='disconnected'?'Connection interrupted. Wait briefly or Disconnect and reconnect.':'Camera connection: '+state);};const offer=await peer.createOffer();if(attempt!==generation)return;await target.setLocalDescription(offer);if(attempt!==generation)return;await api('POST',{type:'offer',sdp:offer.sdp});if(attempt!==generation)return;offerSent=true;for(const candidate of outbound)await api('POST',{type:'candidate',candidate});if(attempt!==generation)return;stopped=false;$('phone-stop').disabled=false;say('Camera on. Waiting for the studio…');poll();}catch(e){if(attempt!==undefined&&attempt!==generation)return;await stop();say(e.name==='NotAllowedError'?'Camera permission was not granted. Allow access in your browser and retry.':e.message||'Camera unavailable.');}};
$('phone-stop').onclick=async()=>{await api('POST',{type:'stop'}).catch(()=>{});await stop();say('Camera disconnected.');};window.addEventListener('pagehide',()=>{stream?.getTracks().forEach(t=>t.stop());peer?.close();});if(slot)$('phone-title').textContent='Phone camera '+slot+'.';
})();
